INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8ef95985-906c-40c7-a64b-e96860b2739d', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$21. óra: Gyakorlóóra: a tanult oszthatósági szabályok alkalmazása$q$, $q$Gyakorlás, igaz-hamis állítások, halmazábrák oszthatóságra.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "3c83a050-8256-41dd-859c-8527666df1e9", "text": "Melyik szám osztható 2-vel, 3-mal és 5-tel is (azaz 30-cal)?", "type": "multiple-choice", "options": [{"id": "cccc9bf8-ea54-4524-be6e-516e7c985bfb", "text": "90", "isCorrect": true}, {"id": "e46763fe-3c26-4a56-8106-7cf66874d6fc", "text": "45", "isCorrect": false}, {"id": "e112e227-ca5e-4f2b-8f5e-05675c6dc4aa", "text": "80", "isCorrect": false}, {"id": "9207bcf7-ae8d-46e9-b2d0-ac5f6224f20a", "text": "100", "isCorrect": false}], "timeLimit": 15}, {"id": "0c8c8134-a566-4c57-8359-5b7493addcc3", "text": "A 180 osztható 4-gyel és 9-cel is.", "type": "true-false", "options": [{"id": "fb361e14-20de-4a9b-a9f4-0a958b9f3100", "text": "Igaz", "isCorrect": true}, {"id": "b91dd06b-d852-43ad-b42c-a8aba7361cd2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "913c523a-b477-40c8-a53c-0ac9db671dc0", "text": "Hány olyan szám van 1 és 100 között, ami osztható 10-zel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "86e76821-cd77-44fa-831f-c9f482bfbb46", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "1e5fea82-a3d2-427b-a48b-aea0d878deeb", "text": "729 (7+2+9=18)", "isCorrect": true}, {"id": "4f4398fa-5100-46d5-985c-ade190f44cc0", "text": "721", "isCorrect": false}, {"id": "27d07635-ccb3-49de-9c83-c01d1b9f580c", "text": "725", "isCorrect": false}, {"id": "8aee4a80-b913-468b-a5c8-db40dc044604", "text": "730", "isCorrect": false}], "timeLimit": 15}, {"id": "93324c19-2e09-442a-aacd-7b5398656dbc", "text": "Ha egy szám osztható 10-zel, akkor 5-tel is osztható.", "type": "true-false", "options": [{"id": "b2ce10de-4408-40a5-89f4-f4a57fbd964d", "text": "Igaz", "isCorrect": true}, {"id": "7d94f4af-4606-4131-8f37-58981c0e76cc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2da22d4b-e65a-4df2-9a94-83a1929e6105", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 5-tel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "f7649ac9-6159-47e5-8456-4524a92429ce", "text": "Melyik a legkisebb háromjegyű szám, ami osztható 3-mal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "102"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('938d8cfd-c685-475e-8703-b38a7d431ff4', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$22. óra: Többszörös, közös többszörös$q$, $q$Közös többszörösök, legkisebb közös többszörös (lkkt) és közös nevező.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "98357b90-f7c6-4284-a019-c3fd59979e31", "text": "Mit jelent két szám legkisebb közös többszöröse (lkkt)?", "type": "multiple-choice", "options": [{"id": "6a0f155f-3a2b-42ae-8a27-92268dd22228", "text": "A legkisebb olyan pozitív számot, amely mindkét számmal osztható", "isCorrect": true}, {"id": "0680fbcc-91a4-4695-9bd6-9389bf7661cd", "text": "A két szám szorzatát mindig", "isCorrect": false}, {"id": "21931930-c2c1-4e13-bfff-38a29de8fb42", "text": "A legkisebb osztót", "isCorrect": false}, {"id": "7e056e04-f024-4f28-a975-6128c7d2841e", "text": "A két szám különbségét", "isCorrect": false}], "timeLimit": 15}, {"id": "4aec618c-c556-4b46-9d29-b66da019f4d8", "text": "Mennyi a 4 és 6 legkisebb közös többszöröse, lkkt(4, 6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "536297f6-9e21-48bc-b553-584a29e2410c", "text": "Mennyi a 3 és 5 legkisebb közös többszöröse, lkkt(3, 5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "cb88f609-d493-442b-8b21-739d6e3c4935", "text": "Relatív prímek (pl. 3 és 5) legkisebb közös többszöröse a két szám szorzata.", "type": "true-false", "options": [{"id": "eadd6871-b3cd-4210-9877-7531123a83dc", "text": "Igaz", "isCorrect": true}, {"id": "f6d6bd81-f710-42de-99d9-3046835b5138", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e7089e84-1056-49b8-9f27-2c70a1994d90", "text": "A közös többszöröst használjuk törtek közös nevezőre hozásakor.", "type": "true-false", "options": [{"id": "c4fb2927-d4fe-45c1-a534-b735653e4be9", "text": "Igaz", "isCorrect": true}, {"id": "6d7329f5-197f-472c-bf5f-8dfbf386a14b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3eb71aad-744b-40fc-9e68-03857d975780", "text": "Mennyi a 6 és 8 legkisebb közös többszöröse?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "3785c95a-dc9f-4e53-919b-32d4e303911c", "text": "Melyik szám közös többszöröse a 2-nek és a 5-nek?", "type": "multiple-choice", "options": [{"id": "33f59980-1e8b-4ac0-9b38-b6e11e4c016b", "text": "10", "isCorrect": true}, {"id": "ee9fa812-db68-41ed-ac29-8aa4b99ed42f", "text": "15", "isCorrect": false}, {"id": "4fbc1221-abbd-4588-8a5e-dbc10fdb1369", "text": "8", "isCorrect": false}, {"id": "3f839eda-e134-4ad6-8ea0-19f70eeb0038", "text": "12", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f86dac29-3d50-40b9-99a5-4f28d0dc2ab7', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$23. óra: Osztó, közös osztó$q$, $q$Közös osztók, legnagyobb közös osztó (lnko) és törtek egyszerűsítése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "e94009dc-1e64-4064-855d-543dba268408", "text": "Mit jelent két szám legnagyobb közös osztója (lnko)?", "type": "multiple-choice", "options": [{"id": "9cdcd68c-2e83-47cd-a98a-ba8ff1353f13", "text": "A legnagyobb olyan pozitív számot, amely mindkét számot osztja", "isCorrect": true}, {"id": "36b627e4-786b-46b2-8423-e6793f57f3d7", "text": "A két szám összege", "isCorrect": false}, {"id": "e45bfd5f-7857-4959-8218-c05846fb087c", "text": "A legkisebb többszöröst", "isCorrect": false}, {"id": "92336f07-9ffa-4727-a053-19f53f962534", "text": "Az 1-et mindig", "isCorrect": false}], "timeLimit": 15}, {"id": "bad855ca-4642-4322-9b27-cc8549636a35", "text": "Mennyi a 12 és 18 legnagyobb közös osztója, lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "da4f8308-be15-468a-8f2a-54cbaecd44b1", "text": "Mennyi a 15 és 25 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "74317143-1db5-46e7-bfe4-0cafe2e5d054", "text": "Két számot relatív prímeknek nevezünk, ha a legnagyobb közös osztójuk 1.", "type": "true-false", "options": [{"id": "3ef2a980-8978-4303-90cc-743dfb2d22ee", "text": "Igaz", "isCorrect": true}, {"id": "16609ff6-7343-40ff-be54-113a95973392", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b6629b86-7c05-4743-8990-969b5ba14d01", "text": "A 8 és 9 relatív prímek (lnko(8,9) = 1).", "type": "true-false", "options": [{"id": "8475df4e-c9dc-4422-bcc3-03e09e88abe5", "text": "Igaz", "isCorrect": true}, {"id": "2ee4bb16-1e40-4a5a-bd93-14d334297385", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "42a1b469-9c0f-4993-a649-70bf5a4976e4", "text": "A legnagyobb közös osztóval egyszerűsítve a törtet a legegyszerűbb alakot kapjuk.", "type": "true-false", "options": [{"id": "59c23789-a61a-4197-9284-eda4d8291d04", "text": "Igaz", "isCorrect": true}, {"id": "33892008-0434-4c26-b952-5f7cdd07593f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bea6bdb8-18d8-4c73-a0ee-f3a9bf680c48", "text": "Mennyi a 20 és 30 legnagyobb közös osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2e278324-03c9-45da-b9af-0d5883ff3ba7', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$24. óra: Összefoglalás$q$, $q$A tanult fogalmak ismétlése, rendszerezése az egész számok és oszthatóság témakörből.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "324c581b-b1c5-4e87-bfde-f825d4e79d34", "text": "Mennyi (-12) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "9976ef55-62b8-4d05-aa58-703c2e985dc9", "text": "Mennyi lkkt(6, 9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "c916e880-9959-476c-b6f0-2b894ff2e034", "text": "Mennyi lnko(24, 36)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "a3286019-ea50-4db7-b1cc-6fa135119239", "text": "A 135 osztható 5-tel és 9-cel is.", "type": "true-false", "options": [{"id": "61af9787-e8cd-46b8-b7ec-886579867354", "text": "Igaz", "isCorrect": true}, {"id": "f6295360-cc38-4755-80f3-9ded5042f4bb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d038c8cc-a5d7-450d-bbfb-c2b5b6d2a7d4", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "72099973-5c00-401d-bfa0-36db1820b1ab", "text": "Igaz", "isCorrect": true}, {"id": "5127b4a6-677e-45f3-90f1-ee39ee7d51ec", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "704f8ef4-841c-4a70-b027-9f4f2032c8b8", "text": "Mennyi (-50) : (+10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "0640c852-8a8c-40d4-a863-ebda2752f9c8", "text": "Melyik szám osztható 4-gyel?", "type": "multiple-choice", "options": [{"id": "54953455-3746-4a2e-9e2d-3a6a2a295924", "text": "524", "isCorrect": true}, {"id": "bc6aec69-80b2-4ac6-ab52-c6009bba1ca4", "text": "522", "isCorrect": false}, {"id": "65949b71-8141-4d55-ae48-9d9955ba529d", "text": "521", "isCorrect": false}, {"id": "8e2a6a90-6c4f-4f3d-a9be-003ce88e7693", "text": "523", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('efdb14d7-c4a3-4b85-9b2f-f8242b183898', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$25. óra: Tesztfeladatok megoldása$q$, $q$Feladatmegoldási gyakorlat önállóan az oszthatósági téma lezárása előtt.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "1c389192-afe7-4b27-903a-5dd8600ad5c6", "text": "Hány osztója van a 10-nek? (1, 2, 5, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "0228573d-ceeb-4521-b828-05e167f6c567", "text": "Osztható-e a 432 6-tal?", "type": "true-false", "options": [{"id": "0a044355-4ee3-47a4-a58a-ec612d11f1b9", "text": "Igaz (páros és 4+3+2=9)", "isCorrect": true}, {"id": "0921e819-aaae-4fab-8743-418a4b8556af", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "10594e1d-6677-4351-835a-503f4e1c7ce9", "text": "Mennyi (-7) * (+6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-42"}, {"id": "a6c4db2a-f5d0-428d-96f4-67cdf8495f7f", "text": "Melyik szorzat eredménye pozitív?", "type": "multiple-choice", "options": [{"id": "78464f65-762d-463b-b314-6b0f1f0766ef", "text": "(-4) * (-5)", "isCorrect": true}, {"id": "2e104d95-bb0a-4b8f-9380-c1ab38570517", "text": "(-4) * (+5)", "isCorrect": false}, {"id": "b04fee71-9511-457c-8378-3eb700a5fe1f", "text": "(+4) * (-5)", "isCorrect": false}, {"id": "92a6e659-3782-4ebd-8952-0886cfae2669", "text": "(-4) * 0", "isCorrect": false}], "timeLimit": 15}, {"id": "56b6c353-9e31-429b-8939-f4a79e29b6b2", "text": "Mennyi a maradék, ha 47-et 5-tel osztunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "3ac85605-8301-4cfb-a0b5-3889b0f6f708", "text": "A 17 prímszám.", "type": "true-false", "options": [{"id": "2854931f-ff1d-445c-a2a8-a877a2d9dfd6", "text": "Igaz", "isCorrect": true}, {"id": "e140c108-2e04-43b2-b201-cb19333fa2ed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "df58b725-d0b1-4409-a9ac-56c5a61bf271", "text": "Mennyi lkkt(4, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('43a0b2c3-8b98-49ab-9bf2-4cdb1def8206', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$26. óra: Témazáró dolgozat$q$, $q$Témazáró számonkérés az Egész számok és oszthatóság témakörből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "609fb30c-4441-4b36-8790-3380c34e44fa", "text": "1. Mennyi (-18) + (+30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "dd3265cf-f7b6-4bae-9fe9-b83341f3c813", "text": "2. Mennyi (-7) * (-9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "63"}, {"id": "5f53a6d2-d127-4be2-8e2a-bb337e90224b", "text": "3. Mennyi (-72) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "465606fa-b49c-483d-9aaf-50ae6af8ce71", "text": "4. Osztható-e a 534 3-mal?", "type": "true-false", "options": [{"id": "0ddea283-0d07-4558-96fd-e0e5de27f8fa", "text": "Igaz (5+3+4=12)", "isCorrect": true}, {"id": "6c04a94e-38de-4090-9485-59dfe905c581", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "93726929-1f51-4491-b2a5-880814df0938", "text": "5. Osztható-e a 620 4-gyel?", "type": "true-false", "options": [{"id": "5ffcdffc-e00c-4f46-9f78-41ac81d7f0d7", "text": "Igaz (20 osztható 4-gyel)", "isCorrect": true}, {"id": "c9c1c596-2baa-41ec-a4ea-8c5239b2793d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9091d236-81ba-4307-8b01-02de9297d605", "text": "6. Mennyi lkkt(6, 10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "c5832765-2c94-4ce2-83af-858775739619", "text": "7. Mennyi lnko(18, 24)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "47d397e9-0c30-4c70-a568-455e667eb6dd", "text": "8. Hány prímszám van 1 és 10 között? (2, 3, 5, 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "a1d696c3-9ca7-4f5d-90be-1bf67851a30b", "text": "9. Hányféleképpen ülhet le 3 gyermek 3 székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "b878bd2c-e688-4b0a-9228-24109b6cfab0", "text": "10. Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "0b68af62-804f-4aba-8520-7aaaa57c55ca", "text": "Igaz", "isCorrect": true}, {"id": "dac403d4-61d9-4970-b22e-a3d106bdf738", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8feea271-2c08-46e0-84c4-591a391cf9b8', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$27. óra: Témazáró dolgozat értékelése$q$, $q$A témazáró dolgozat megbeszélése, hibák elemzése, tapasztalatok összegzése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "df785cab-b81d-48ff-ba6f-1d63eaa935cb", "text": "Mi volt a leggyakoribb hiba az előjelszabályok alkalmazásakor?", "type": "multiple-choice", "options": [{"id": "ce555827-138a-4046-a4f1-d1895305a958", "text": "A szorzás/osztás és összeadás előjelszabályainak összetévesztése", "isCorrect": true}, {"id": "2555c6b8-734f-4463-9514-7209beb136ba", "text": "A számok leírása", "isCorrect": false}, {"id": "61716509-595d-478b-b836-e4745abdf9f4", "text": "A vonalzó használata", "isCorrect": false}, {"id": "850b14c1-9676-4962-861c-ceedbdb5aca2", "text": "A válasz elhagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "2efab8ed-e860-4383-b2c9-6737d62541f6", "text": "Az osztási szabályok (pl. 3-mal, 9-cel) esetén a számjegyek összege a döntő.", "type": "true-false", "options": [{"id": "cf9d5773-104e-4aef-a367-674ecaae557d", "text": "Igaz", "isCorrect": true}, {"id": "c518a30f-4884-4286-ae4e-42738a0f3f10", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "96cf0d93-b317-4b74-9665-256e357df04e", "text": "Mennyi (-5) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "97165004-711e-4224-b964-0c6dc896e84d", "text": "A lkkt meghatározásánál a többszörösök közül a legkisebbet választjuk.", "type": "true-false", "options": [{"id": "54170df1-5aa0-4aed-99cb-5148dbb3b152", "text": "Igaz", "isCorrect": true}, {"id": "bcca5e12-4332-4772-bd01-82c4a9532b63", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9b518a25-1b6c-4e30-9fd8-2e1a5cd6e3ff", "text": "Mennyi (-30) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "26ba651f-4c9d-4358-bac3-28226e75f8ed", "text": "A dolgozatok áttekintése segít a hiányosságok pótlásában.", "type": "true-false", "options": [{"id": "6f327338-16df-45cd-b6e7-7d073a89ed35", "text": "Igaz", "isCorrect": true}, {"id": "bca0e83e-623b-4c5a-ae22-3f2e000ed0bd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4751c6f2-056e-4425-84f9-408535f268ce", "text": "Mennyi lnko(10, 15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('12ef3cb8-4fa1-43cd-8d7c-8cf619414974', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$28. óra: Mit tanultunk a törtekről? Ismétlés$q$, $q$Ötödikben tanult ismeretek: közönséges tört értelmezése, számláló, nevező, bővítés, egyszerűsítés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "3db5f608-9c45-418b-84f4-8475d3a422b7", "text": "Mi a közönséges tört felső száma?", "type": "multiple-choice", "options": [{"id": "8e6cdcc0-fd0b-4352-8493-4130001fd4ba", "text": "Számláló", "isCorrect": true}, {"id": "ab8dbdaf-e996-41b7-8c41-49ea33ceab33", "text": "Nevező", "isCorrect": false}, {"id": "f9d6e0e8-79fa-4aa5-914d-a7ee8c469b3c", "text": "Törtvonal", "isCorrect": false}, {"id": "fd2bd174-2e25-4f8a-af3c-c4d144db3833", "text": "Egész rész", "isCorrect": false}], "timeLimit": 15}, {"id": "576cd6c3-0ef5-4446-b6bb-4bdda8c899cc", "text": "Mi a közönséges tört alsó száma?", "type": "multiple-choice", "options": [{"id": "c2fc51fd-deab-4f6a-8381-3b4a4bc54c7c", "text": "Nevező", "isCorrect": true}, {"id": "c5447b57-80af-4c56-8a0e-85c47bd9e976", "text": "Számláló", "isCorrect": false}, {"id": "817855f0-e92e-48fc-937e-8ad93fbbab45", "text": "Osztó", "isCorrect": false}, {"id": "75c6ec61-4665-4d99-b14c-a5c8bebe68dc", "text": "Különbség", "isCorrect": false}], "timeLimit": 15}, {"id": "5d0dc8f6-a473-49cb-8e05-616164366e47", "text": "Mennyi a 3/4 bővítve 2-vel?", "type": "multiple-choice", "options": [{"id": "eeefde35-c2db-458d-9d64-25e9c9720494", "text": "6/8", "isCorrect": true}, {"id": "0a7c0fe6-e60d-40d5-af75-90fbfc617ee8", "text": "5/6", "isCorrect": false}, {"id": "86d34e94-421c-4349-afd8-aed4c1df8aa5", "text": "3/8", "isCorrect": false}, {"id": "ffbecd10-64cf-4a6a-815f-d875361caaf1", "text": "6/4", "isCorrect": false}], "timeLimit": 15}, {"id": "1a3daa3e-9d15-421a-be2e-6f09446a56b6", "text": "Mennyi a 6/10 egyszerűsítve 2-vel?", "type": "multiple-choice", "options": [{"id": "3d6050b8-cb7e-44b2-b9f2-252c0127a3dd", "text": "3/5", "isCorrect": true}, {"id": "c4d84b1f-68aa-4bbb-b71a-89918a9ed364", "text": "3/10", "isCorrect": false}, {"id": "d71f68d6-3d16-4dd6-b4af-10dc43ed8412", "text": "6/5", "isCorrect": false}, {"id": "ad738143-ed7a-4894-8472-96cb73e8bacb", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "6a69b03a-44b4-4055-8712-2e8428f903b5", "text": "A tört értéke nem változik, ha számlálóját és nevezőjét ugyanazzal a nem-nulla számmal szorozzuk (bővítjük).", "type": "true-false", "options": [{"id": "fa3cbb0f-5dd4-4a60-8a83-c313dc214890", "text": "Igaz", "isCorrect": true}, {"id": "122cba77-dbdb-4950-968f-b2b90f4ad3c1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "095ef47f-752d-4520-ac03-59e9755e21e7", "text": "Hány negyedből áll 1 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "205d43d2-be27-4e09-85c3-c416187d5c4a", "text": "Mennyi 1/2 + 1/4?", "type": "multiple-choice", "options": [{"id": "a89c4e97-9c09-48f9-ae68-6a5ccdfb87cb", "text": "3/4 (2/4 + 1/4)", "isCorrect": true}, {"id": "17e8ce0f-1428-492b-977e-f6eb12e43fcd", "text": "2/6", "isCorrect": false}, {"id": "a7f1c562-0ac4-4657-a1bd-6787fdf3f711", "text": "2/4", "isCorrect": false}, {"id": "066b1f9b-78f1-4f8e-b222-3226b217f228", "text": "1/6", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f794e0e4-fe24-441d-941c-96ec6f8a8506', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$29. óra: Mit tanultunk a törtekről? Ismétlés II.$q$, $q$Összeadás és kivonás azonos és különböző nevezőjű törtekkel.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "2f21064b-3295-4baf-a93a-a8e04bf73a5b", "text": "Hogyan adjuk össze a különböző nevezőjű törteket?", "type": "multiple-choice", "options": [{"id": "846836fa-1646-403d-9eba-cff2d690b761", "text": "Közös nevezőre hozzuk őket, majd a számlálókat összeadjuk", "isCorrect": true}, {"id": "470dfda4-f97a-4a5a-a11a-fe2853a36e0e", "text": "A számlálókat és nevezőket is összeadjuk", "isCorrect": false}, {"id": "88a019ee-c422-4981-a34d-211d15b9a784", "text": "A számlálókat megszorozzuk", "isCorrect": false}, {"id": "27053b48-02f3-46c0-9ce3-4594d2233bae", "text": "Nem lehet összeadni őket", "isCorrect": false}], "timeLimit": 15}, {"id": "d0161561-ef89-44f6-9220-5c38d9cc8a91", "text": "Mennyi 1/3 + 1/6? (2/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "d5df671c-6358-4584-afd6-01d1435cf983", "text": "3/6 (azaz 1/2)", "isCorrect": true}, {"id": "25257528-fe5b-4aa8-8653-d9812cce609b", "text": "2/9", "isCorrect": false}, {"id": "77329f51-a4fe-4d1f-9f04-af8538f59efe", "text": "1/9", "isCorrect": false}, {"id": "454f118d-91ef-4e55-b689-33dbb723413e", "text": "2/6", "isCorrect": false}], "timeLimit": 15}, {"id": "54459261-eabb-42ce-ace3-319864517e2e", "text": "Mennyi 5/8 - 3/8?", "type": "multiple-choice", "options": [{"id": "a9232863-6d2f-4b43-aaa3-28379059283e", "text": "2/8 (azaz 1/4)", "isCorrect": true}, {"id": "6ccfbd4c-1c6b-4746-9119-2d0e75b84fc4", "text": "2/0", "isCorrect": false}, {"id": "be990208-48c2-4167-be68-da8f42fe1aa9", "text": "8/8", "isCorrect": false}, {"id": "59b8b5b7-faee-4274-90a5-74440f45aba2", "text": "1/8", "isCorrect": false}], "timeLimit": 15}, {"id": "bfe8a8cd-3597-4094-a312-8834cf8b2d3a", "text": "Az 1/2 és 2/4 egyenlő értékű törtek.", "type": "true-false", "options": [{"id": "2340b59f-56e2-411e-88e6-02a4c842eb8e", "text": "Igaz", "isCorrect": true}, {"id": "6dcc65a7-aadd-47d7-895c-1807e8a8ab7f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4481ec97-c585-4867-8471-cc1c7ff34a5d", "text": "Hány nyolcad van 3/4-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "5ee5fd25-c667-4425-aaa0-80e108440848", "text": "Mennyi 1 egészből kivonva 2/5-öt?", "type": "multiple-choice", "options": [{"id": "83394d39-b439-40c6-afb6-0ec309f74248", "text": "3/5", "isCorrect": true}, {"id": "983c5f37-5298-48ac-8b92-251f88f87656", "text": "1/5", "isCorrect": false}, {"id": "7701a3b4-7438-4bb2-9d55-07237c0100f6", "text": "2/5", "isCorrect": false}, {"id": "4d0f7ae0-9257-4cac-a812-406caa99404d", "text": "5/5", "isCorrect": false}], "timeLimit": 15}, {"id": "51bba817-efff-4ca8-b59c-13b4ce12b4f1", "text": "A törtvonal osztás műveletet jelent.", "type": "true-false", "options": [{"id": "4e759298-6ef5-451d-a197-0b908b1d84e5", "text": "Igaz", "isCorrect": true}, {"id": "bbf33cf7-61d9-45fe-8e54-1ca2b3a7b515", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3be7ec44-43dc-43fa-a096-3522d053a563', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$30. óra: Szorzás törttel, a reciprok$q$, $q$Tört szorzása törttel, reciprok fogalma.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Törtek$q$, $q$[{"id": "8ac845fe-b2d4-4c6b-8501-91aa85cdcf0c", "text": "Hogyan szorzunk törttel törtet?", "type": "multiple-choice", "options": [{"id": "43223db4-d120-4160-b182-f6d5d58e3c24", "text": "A számlálót a számlálóval, a nevezőt a nevezővel szorozzuk", "isCorrect": true}, {"id": "9ccd6ed9-7e3a-4589-95a6-03a4853a20a5", "text": "Közös nevezőre hozzuk őket", "isCorrect": false}, {"id": "4d6c8936-f17a-4a86-ab3d-0dcc4a144e7a", "text": "A számlálót a nevezővel szorozzuk", "isCorrect": false}, {"id": "328067b7-0fc7-4a4f-90a2-f1c8c069a81c", "text": "Keresztbe szorzunk", "isCorrect": false}], "timeLimit": 15}, {"id": "248c16fb-69e7-41ee-a8da-5313a386a1cc", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "97a693a5-c18b-472d-8cba-5c138585dcc9", "text": "6/15 (azaz 2/5)", "isCorrect": true}, {"id": "5b6fc922-5342-4146-ae6c-a818e4800d25", "text": "5/8", "isCorrect": false}, {"id": "66c43762-a20a-41ca-92d1-29db7acae87a", "text": "6/8", "isCorrect": false}, {"id": "65ab92de-ae7b-448e-b49f-b6c739315d86", "text": "2/15", "isCorrect": false}], "timeLimit": 15}, {"id": "754e7154-a9b2-4bd5-9594-694bfa3768f3", "text": "Mi a 3/4 reciproka?", "type": "multiple-choice", "options": [{"id": "21b185e0-d747-4f59-b887-c304e7a47a88", "text": "4/3", "isCorrect": true}, {"id": "fd2b48b6-081e-4cf2-99cd-26f8af568c1b", "text": "-3/4", "isCorrect": false}, {"id": "932d998f-72c3-4dbb-b20a-3a294fd687dc", "text": "1/4", "isCorrect": false}, {"id": "24de7f94-203d-4ff0-a0b8-41a682b96dd1", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "7e882206-5e38-465a-b290-5bca2dc503ae", "text": "Egy szám és a reciproka szorzata mindig 1.", "type": "true-false", "options": [{"id": "4b2158d5-bcfc-4e2c-ab4f-2b1b1f7f5166", "text": "Igaz", "isCorrect": true}, {"id": "109a9d43-5c11-4578-93ef-7df446802ed7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "72f953b1-07ce-45fa-8efd-6457823077c4", "text": "Mi a 5 egész reciproka?", "type": "multiple-choice", "options": [{"id": "246863cb-046d-450d-b75e-4ce176a00019", "text": "1/5", "isCorrect": true}, {"id": "eccd4d81-5a92-492a-b5e8-4e85440e7ed9", "text": "-5", "isCorrect": false}, {"id": "80e831d4-25e0-4d71-82ec-af8e7f380199", "text": "5/1", "isCorrect": false}, {"id": "514b5093-20d6-4ca0-9931-baaea2942f6c", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "19a9cd71-58f4-4caf-8fd8-42791592efc9", "text": "A 0-nak nincs reciproka.", "type": "true-false", "options": [{"id": "64019894-825d-4a40-b1d6-6f109027cbb2", "text": "Igaz", "isCorrect": true}, {"id": "971242fd-17e6-482f-8163-ee5517cd745a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "34fbf211-0e18-4b31-ac81-1f97578c1172", "text": "Mennyi 1/2 * 1/3?", "type": "multiple-choice", "options": [{"id": "2d5f98c5-ee1b-435c-ba7a-73bbecaf862d", "text": "1/6", "isCorrect": true}, {"id": "25dd4584-88c3-4d91-8882-0cf26c4d0b51", "text": "2/5", "isCorrect": false}, {"id": "ef658091-85ed-4223-b99a-14511a67f987", "text": "1/5", "isCorrect": false}, {"id": "7bb2c7fd-b8d4-44d0-92a9-5390e2bf9a86", "text": "2/6", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;